input.query:
PREFIX schema: <https://schema.org/> PREFIX aw: <https://w3id.org/agentweb-testbed#>
SELECT ?name ?id ?pname ?rate ?apr ?term ?type ?pts ?loan ?pay ?close WHERE {
?p a schema:MortgageLoan; schema:name ?name; schema:identifier ?id; schema:provider ?pr; schema:interestRate ?rate; schema:annualPercentageRate ?apr; schema:loanTerm [schema:value ?term]; aw:rateType ?type; aw:exampleLoanAmount [schema:value ?loan]; aw:estimatedMonthlyPayment [schema:value ?pay]; aw:estimatedClosingCosts [schema:value ?close].
?pr schema:name ?pname.
OPTIONAL {?p aw:discountPoints ?pts}
} ORDER BY ?rate

